def ship_within_days(weights: list[int], days: int) -> int:
    def needed(cap: int) -> int:
        d, load = 1, 0
        for w in weights:
            if load + w > cap:
                d += 1
                load = 0
            load += w
        return d

    lo, hi = max(weights), sum(weights)
    while lo < hi:
        mid = lo + (hi - lo) // 2
        if needed(mid) <= days:
            hi = mid
        else:
            lo = mid + 1
    return lo
